(* [comment removed for export] *)
(* [comment removed for export] *)
Definition rs_doread1_post (sp : word) (spa : Z) (gp tp : word) (E : Z) (a7 : word) (tot fb ff : Z) (s5x s6x t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo fp : Z) (FB : fbv) (hw : word) (optc : list cell) (j56 : list byte) (ectc : list cell) (j120 : list byte) (eb : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a5 a6 m',
       ms' = rs_ms P_A_FB_DYN_PREPARE (Z_to_bv 64 RS_DBPRET) sp spa gp tp t0 t1 t2 E
                   (wz (ff + 32)) (wz fb) (wz (read_size_val FB)) (wz E) (wz 7) a5 a6 a7 tot fb ff s5x s6x t3 t4 t5 t6 F fc m'
    /\ munch [(lo, spa); (Z.shiftr ff 3 + 2147450880 + 4, Z.shiftr ff 3 + 2147450880 + 7)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo spa
    /\ rs_fake m' ff fp hw optc j56 ectc j120 0 eb.

Lemma rs_doread1 : forall rax sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5x s6x t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (LF : list fframe) (lo spa ff fp E fb tot eb : Z) (LB : list block) (FB : fbv) (ds : list byte)
    (hw : word) (optc : list cell) (j56 : list byte) (ectc : list cell) (j120 : list byte),
  rs_fake m ff fp hw optc j56 ectc j120 248 eb -> fresh_frame H LF 2 ff fp ->
  AFlatBuf LB m fb FB ds -> fb mod 8 = 0 -> aapp fb SZ_FB -> accessible m fb SZ_FB ->
  stk bsegs m lo spa -> lo + AREAD_SIZE_STACK <= spa -> aceil <= lo -> 0 <= spa < 2^64 ->
  0 <= E -> E + 24 < 2^64 ->
  mem_inv bsegs m -> ACONST m ->
  evt bsegs (rs_doread1_post sp spa gp tp E a7 tot fb ff s5x s6x t3 t4 t5 t6 F fc lo fp FB hw optc j56 ectc j120 eb m)
